Client script (unity_bridge_client.js):
```js
const net = require('net');
const fs = require('fs');

const PORT = 62067;
const HOST = 'localhost';

const commandFile = process.argv[2];
const outputFile = process.argv[3];
const scriptText = fs.readFileSync(commandFile, 'utf8');

const socket = net.connect(PORT, HOST);
let buffer = Buffer.alloc(0);
let handshaken = false;
let welcomeDone = false;
let clientIdSent = false;
let currentRequestId = null;
let done = false;

function frame(payloadBuffer) {
  const len = Buffer.alloc(8);
  len.writeBigUInt64BE(BigInt(payloadBuffer.length));
  return Buffer.concat([len, payloadBuffer]);
}

socket.on('connect', () => {});
socket.on('data', (chunk) => {
  buffer = Buffer.concat([buffer, chunk]);
  if (!welcomeDone) {
    const s = buffer.toString('ascii');
    if (s.includes('\n') || s.length >= 4096) {
      const line = s.trim();
      welcomeDone = true;
      console.log('[WELCOME]', line);
      const m = line.match(/SERVER_VERSION=(\d+)/);
      const serverVersion = m ? parseInt(m[1]) : 1;
      if (serverVersion >= 2) {
        socket.write(frame(Buffer.from('CLIENT_VERSION=2', 'utf8')));
      }
      socket.write(frame(Buffer.from('PLATFORM=cli', 'utf8')));
      // send command
      const req = JSON.stringify({type: 'execute_csharp_script', params: {script: scriptText, summary: 'build tassels', execution_mode: 'editor'}, request_id: 'ntb-1'});
      socket.write(frame(Buffer.from(req, 'utf8')));
      // strip the welcome line bytes from buffer: find the newline
      const nl = buffer.indexOf(10);
      buffer = buffer.subarray(nl + 1);
      currentRequestId = 'ntb-1';
    }
  }
  if (welcomeDone) {
    // parse frames
    for (;;) {
      if (buffer.length < 8) break;
      const len = buffer.readBigUInt64BE(0);
      if (len === 0n) { buffer = buffer.subarray(8); continue; }
      if (len > 64n * 1024n * 1024n) { console.error('Invalid framed length'); process.exit(1); }
      const total = 8 + Number(len);
      if (buffer.length < total) break;
      const payload = Buffer.from(buffer.subarray(8, total));
      buffer = buffer.subarray(total);
      handleFrame(payload);
    }
  }
});

function handleFrame(payload) {
  let obj = null;
  try { obj = JSON.parse(payload.toString('utf8')); } catch {}
  if (obj && typeof obj === 'object' && typeof obj.notification_type === 'string') {
    console.log('[NOTIFICATION]', JSON.stringify(obj));
    return;
  }
  if (obj && typeof obj === 'object' && obj.success === true && obj.message === 'pong') {
    console.log('[PONG]');
    return;
  }
  if (obj && typeof obj === 'object' && typeof obj.request_id === 'string') {
    if (obj.request_id === currentRequestId) {
      fs.writeFileSync(outputFile, JSON.stringify(obj, null, 2));
      console.log('[RESPONSE] written to', outputFile);
      socket.end();
      setTimeout(() => process.exit(0), 200);
    }
    return;
  }
  console.log('[FRAME]', payload.toString('utf8').substring(0, 500));
}

socket.on('error', (e) => { console.error('SOCKET ERROR', e.message); process.exit(1); });
socket.on('close', () => { if (!done) { console.error('Closed before response'); process.exit(1); } });

// timeout watchdog
setTimeout(() => { console.error('TIMEOUT'); process.exit(2); }, 120000);
```

