// Codely Unity Bridge TCP client (protocol extracted from codely.exe / NativeTcpBridge)
// Usage: node unity_bridge_client.js <commandFile.json> <responseOut.json>
const net = require('net');
const fs = require('fs');

const PORT = 62067;
const HOST = 'localhost';
const commandFile = process.argv[2];
const outputFile = process.argv[3];
const command = JSON.parse(fs.readFileSync(commandFile, 'utf8'));

let buffer = Buffer.alloc(0);
let welcomeDone = false;
let gotResponse = false;

function frame(payloadBuffer) {
  const len = Buffer.alloc(8);
  len.writeBigUInt64BE(BigInt(payloadBuffer.length));
  return Buffer.concat([len, payloadBuffer]);
}

const socket = net.connect(PORT, HOST);
socket.setNoDelay(true);

socket.on('error', (e) => {
  console.error('SOCKET_ERROR: ' + e.message);
  process.exit(1);
});

socket.on('close', () => {
  if (!gotResponse) {
    console.error('CLOSED_BEFORE_RESPONSE');
    process.exit(3);
  }
});

socket.on('data', (chunk) => {
  buffer = Buffer.concat([buffer, chunk]);

  if (!welcomeDone) {
    const nl = buffer.indexOf(10);
    if (nl < 0 && buffer.length < 4096) return;
    const line = buffer.toString('ascii', 0, nl >= 0 ? nl : buffer.length).trim();
    buffer = nl >= 0 ? buffer.subarray(nl + 1) : Buffer.alloc(0);
    welcomeDone = true;
    console.log('[WELCOME] ' + line);
    const m = line.match(/SERVER_VERSION=(\d+)/);
    const serverVersion = m ? parseInt(m[1], 10) : 1;
    if (serverVersion >= 2) {
      socket.write(frame(Buffer.from('CLIENT_VERSION=2', 'utf8')));
    }
    socket.write(frame(Buffer.from('PLATFORM=cli', 'utf8')));
    const req = JSON.stringify({
      type: command.type,
      params: command.params || {},
      request_id: 'ntb-1'
    });
    console.log('[SENT] type=' + command.type + ' bytes=' + req.length);
    socket.write(frame(Buffer.from(req, 'utf8')));
  }

  // frame loop
  for (;;) {
    if (buffer.length < 8) break;
    const len = buffer.readBigUInt64BE(0);
    if (len === 0n) { buffer = buffer.subarray(8); continue; }
    if (len > 64n * 1024n * 1024n) {
      console.error('INVALID_FRAME_LEN ' + len);
      process.exit(1);
    }
    const total = 8 + Number(len);
    if (buffer.length < total) break;
    const payload = Buffer.from(buffer.subarray(8, total));
    buffer = buffer.subarray(total);
    handleFrame(payload);
  }
});

function handleFrame(payload) {
  let obj = null;
  try { obj = JSON.parse(payload.toString('utf8')); } catch (e) { obj = null; }

  if (obj && typeof obj === 'object' && typeof obj.notification_type === 'string') {
    console.log('[NOTIFY] ' + JSON.stringify(obj).substring(0, 300));
    return;
  }
  if (obj && typeof obj === 'object' && obj.success === true && obj.message === 'pong') {
    console.log('[PONG]');
    gotResponse = true;
    socket.end();
    setTimeout(() => process.exit(0), 200);
    return;
  }
  if (obj && typeof obj === 'object' && typeof obj.request_id === 'string') {
    if (obj.request_id === 'ntb-1') {
      fs.writeFileSync(outputFile, JSON.stringify(obj, null, 2));
      console.log('[RESPONSE] ' + (obj.success ? 'SUCCESS' : 'FAILURE') + ' -> ' + outputFile);
      gotResponse = true;
      socket.end();
      setTimeout(() => process.exit(0), 300);
    } else {
      console.log('[DROP_RESPONSE] request_id=' + obj.request_id);
    }
    return;
  }
  console.log('[UNMATCHED_FRAME] ' + payload.toString('utf8').substring(0, 400));
}

const watchdog = setTimeout(() => {
  console.error('TIMEOUT_NO_RESPONSE');
  process.exit(2);
}, 180000);
watchdog.unref();

