// Build two miHoYo-style wide skirt-tassel drapes on Kazuko, with same-family edge trim.
// Rigid now (bone chains under Root_M), cloth-sim-ready later via Magica Cloth BoneCloth.
var prefabPath = "Assets/Prefabs/Kazuko.prefab";
if (EditorApplication.isPlayingOrWillChangePlaymode)
    return "ERROR: Unity is in play mode, cannot modify prefab.";

var contents = PrefabUtility.LoadPrefabContents(prefabPath);
var report = new System.Text.StringBuilder();
try
{
    Transform Find(string n)
    {
        foreach (var t in contents.GetComponentsInChildren<Transform>(true))
            if (t.name == n) return t;
        return null;
    }

    var hipL = Find("Hip_L");
    var hipR = Find("Hip_R");
    var eyeL = Find("Eye1_L");
    var eyeR = Find("Eye1_R");
    var headM = Find("Head_M");
    var rootM = Find("Root_M");
    var root = contents.transform;
    if (hipL == null || hipR == null || rootM == null || eyeL == null || eyeR == null)
        return "ERROR: key bones not found";

    Vector3 pelvis = (hipL.position + hipR.position) * 0.5f;

    Vector3 fwd = ((eyeL.position + eyeR.position) * 0.5f - (headM != null ? headM.position : pelvis));
    fwd.y = 0f;
    fwd = fwd.sqrMagnitude > 1e-8f ? fwd.normalized : Vector3.forward;
    Vector3 rightDir = Vector3.Cross(Vector3.up, fwd).normalized;
    report.AppendLine($"pelvis=({pelvis.x:F3},{pelvis.y:F3},{pelvis.z:F3}) fwd=({fwd.x:F3},{fwd.y:F3},{fwd.z:F3}) right=({rightDir.x:F3},{rightDir.y:F3},{rightDir.z:F3})");

    // ---------- texture: cloth base + same-family trim (edge binding) ----------
    int TW = 256, TH = 512;
    var tex = new Texture2D(TW, TH, TextureFormat.RGBA32, false);
    Color baseC = new Color(0.723f, 0.672f, 0.589f);
    Color trimC = new Color(0.208f, 0.166f, 0.154f);
    Color accentC = new Color(0.85f, 0.80f, 0.68f);
    for (int y = 0; y < TH; y++)
    {
        float v = (float)y / (TH - 1);
        for (int x = 0; x < TW; x++)
        {
            float u = (float)x / (TW - 1);
            Color c;
            bool edge = u < 0.045f || u > 0.955f;
            bool edgeAcc = !edge && (u < 0.075f || u > 0.925f);
            bool top = v > 0.96f;
            bool topAcc = !top && v > 0.92f;
            bool bot = v < 0.09f;
            bool botAcc = !bot && v < 0.155f;
            if (edge || top || bot) c = trimC;
            else if (edgeAcc || topAcc || botAcc) c = accentC;
            else
            {
                float weave = ((x / 4) % 2 == 0) ? 1.0f : 0.96f;
                float grad = Mathf.Lerp(0.97f, 1.02f, v);
                c = baseC * (weave * grad);
            }
            tex.SetPixel(x, y, c);
        }
    }
    tex.Apply();
    string texPath = "Assets/Textures/Kazuko/Kazuko_SkirtTassel.png";
    System.IO.File.WriteAllBytes(texPath, tex.EncodeToPNG());
    UnityEngine.Object.DestroyImmediate(tex);
    AssetDatabase.ImportAsset(texPath);
    var importer = (TextureImporter)AssetImporter.GetAtPath(texPath);
    if (importer != null)
    {
        importer.sRGBTexture = true;
        importer.mipmapEnabled = true;
        importer.wrapMode = TextureWrapMode.Repeat;
        importer.SaveAndReimport();
    }
    var texAsset = AssetDatabase.LoadAssetAtPath<Texture2D>(texPath);
    if (texAsset == null) return "ERROR: texture import failed";
    report.AppendLine("tex OK " + texPath);

    // ---------- material: same toon shader/params as kazuko_cloth ----------
    var cloth = AssetDatabase.LoadAssetAtPath<Material>("Assets/Arts/Materials/kazuko/kazuko_cloth.mat");
    if (cloth == null) return "ERROR: kazuko_cloth.mat not found";
    string matPath = "Assets/Arts/Materials/kazuko/kazuko_skirt_tassel.mat";
    if (AssetDatabase.LoadAssetAtPath<Material>(matPath) != null) AssetDatabase.DeleteAsset(matPath);
    var mat = new Material(cloth.shader);
    mat.CopyPropertiesFromMaterial(cloth);
    mat.SetTexture("_MainTex", texAsset);
    mat.SetColor("_MainColor", Color.white); // texture carries the color
    mat.name = "kazuko_skirt_tassel";
    AssetDatabase.CreateAsset(mat, matPath);
    report.AppendLine("mat OK " + matPath);

    // ---------- remove previous tassel objects (idempotent rebuild) ----------
    var toDestroy = new System.Collections.Generic.List<GameObject>();
    foreach (var t in contents.GetComponentsInChildren<Transform>(true))
        if (t.name.StartsWith("SkirtTassel")) toDestroy.Add(t.gameObject);
    foreach (var g in toDestroy) UnityEngine.Object.DestroyImmediate(g);
    if (toDestroy.Count > 0) report.AppendLine("removed " + toDestroy.Count + " old tassel objects");

    // ---------- geometry params ----------
    float topY = 0.985f, botY = 0.24f, toothRise = 0.07f;
    int rows = 13, cols = 9;

    // runtime ground-truth test for triangle winding convention
    bool crossIsFront;
    {
        var testMesh = new Mesh();
        testMesh.vertices = new Vector3[] { new Vector3(0, 0, 0), new Vector3(1, 0, 0), new Vector3(0, 1, 0) };
        testMesh.triangles = new int[] { 0, 1, 2 };
        testMesh.RecalculateNormals();
        crossIsFront = testMesh.normals[0].z > 0f;
        UnityEngine.Object.DestroyImmediate(testMesh);
    }
    report.AppendLine("winding crossIsFront=" + crossIsFront);

    SkinnedMeshRenderer BuildSide(int sideSign, string sideName)
    {
        Vector3 sideDir = rightDir * sideSign;
        Vector3 normal = (sideDir * Mathf.Cos(15f * Mathf.Deg2Rad) + fwd * Mathf.Sin(15f * Mathf.Deg2Rad)).normalized;
        Vector3 binorm = Vector3.Cross(Vector3.up, normal).normalized;

        Vector3 CenterAt(float t)
        {
            float lat = 0.14f, fw = 0.045f;
            float tk = Mathf.InverseLerp(0.833f, 1f, t);
            lat = Mathf.Lerp(lat, 0.085f, tk);
            fw = Mathf.Lerp(fw, 0.02f, tk);
            Vector3 c = pelvis + sideDir * lat + fwd * fw;
            c.y = Mathf.Lerp(botY, topY, t);
            return c;
        }
        float HalfW(float t) { return Mathf.Lerp(0.10f, 0.085f, t); }

        // vertices (world space)
        var verts = new System.Collections.Generic.List<Vector3>();
        var uvs = new System.Collections.Generic.List<Vector2>();
        for (int i = 0; i < rows; i++)
        {
            float t = (float)i / (rows - 1);
            Vector3 c = CenterAt(t);
            float hw = HalfW(t);
            for (int cI = 0; cI < cols; cI++)
            {
                float u = (float)cI / (cols - 1);
                Vector3 p = c + binorm * ((u * 2f - 1f) * hw);
                float k = u * 2f - 1f;
                p += normal * (0.012f * (1f - k * k)); // slight convexity
                if (i == 0 && (cI % 2) == 1) p += Vector3.up * toothRise; // fringe teeth
                verts.Add(p);
                uvs.Add(new Vector2(u, t));
            }
        }
        var tris = new System.Collections.Generic.List<int>();
        for (int i = 0; i < rows - 1; i++)
        {
            for (int cI = 0; cI < cols - 1; cI++)
            {
                int i0 = i * cols + cI, i1 = i * cols + cI + 1, i2 = (i + 1) * cols + cI + 1, i3 = (i + 1) * cols + cI;
                if (crossIsFront) { tris.AddRange(new int[] { i0, i1, i2, i0, i2, i3 }); }
                else { tris.AddRange(new int[] { i0, i2, i1, i0, i3, i2 }); }
            }
        }
        // double-sided back copy
        int vCount = verts.Count;
        var nrm = new System.Collections.Generic.List<Vector3>();
        for (int vi = 0; vi < vCount; vi++) nrm.Add(normal);
        for (int vi = 0; vi < vCount; vi++) { verts.Add(verts[vi]); uvs.Add(uvs[vi]); nrm.Add(-normal); }
        for (int ti = 0; ti < tris.Count; ti += 3)
            tris.AddRange(new int[] { vCount + tris[ti + 2], vCount + tris[ti + 1], vCount + tris[ti] });

        // bone chain (4 bones top->bottom, for future Magica Cloth BoneCloth)
        var boneTs = new Transform[4];
        Transform parentB = rootM;
        for (int b = 0; b < 4; b++)
        {
            var bgo = new GameObject("SkirtTasselBone_" + sideName + (b + 1));
            bgo.transform.SetParent(parentB, false);
            bgo.transform.position = CenterAt(1f - b / 3f);
            bgo.transform.rotation = Quaternion.identity;
            parentB = bgo.transform;
            boneTs[b] = bgo.transform;
        }

        // tassel GO (identity local under prefab root)
        var tgo = new GameObject("SkirtTassel_" + sideName);
        tgo.transform.SetParent(root, false);
        Matrix4x4 go2world = tgo.transform.localToWorldMatrix;

        // convert verts to GO-local space
        for (int vi = 0; vi < verts.Count; vi++) verts[vi] = tgo.transform.InverseTransformPoint(verts[vi]);

        var mesh = new Mesh();
        mesh.name = "Kazuko_SkirtTassel_" + sideName;
        mesh.SetVertices(verts);
        mesh.SetUVs(0, uvs);
        mesh.SetNormals(nrm);
        mesh.SetTriangles(tris, 0);

        var binds = new Matrix4x4[4];
        for (int b = 0; b < 4; b++) binds[b] = boneTs[b].worldToLocalMatrix * go2world;
        mesh.bindposes = binds;
        var bw = new BoneWeight[verts.Count];
        for (int vi = 0; vi < verts.Count; vi++)
        {
            float f = (1f - uvs[vi].y) * 3f;
            int b0 = Mathf.Clamp(Mathf.FloorToInt(f), 0, 3);
            int b1 = Mathf.Min(b0 + 1, 3);
            float w1 = Mathf.Clamp(f - b0, 0f, 1f);
            bw[vi] = new BoneWeight { boneIndex0 = b0, weight0 = 1f - w1, boneIndex1 = b1, weight1 = w1 };
        }
        mesh.boneWeights = bw;
        mesh.RecalculateBounds();

        string meshPath = "Assets/Arts/Models/Main Characters/kazuko/Kazuko_SkirtTassel_" + sideName + ".asset";
        if (AssetDatabase.LoadAssetAtPath<Mesh>(meshPath) != null) AssetDatabase.DeleteAsset(meshPath);
        AssetDatabase.CreateAsset(mesh, meshPath);
        report.AppendLine("mesh OK " + meshPath + " verts=" + verts.Count);

        var smr = tgo.AddComponent<SkinnedMeshRenderer>();
        smr.sharedMesh = mesh;
        smr.bones = boneTs;
        smr.rootBone = boneTs[0];
        smr.sharedMaterial = mat;
        smr.updateWhenOffscreen = true;
        smr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.On;
        smr.receiveShadows = true;
        smr.localBounds = new Bounds(mesh.bounds.center, mesh.bounds.size * 1.3f);
        return smr;
    }

    var smrR = BuildSide(+1, "R");
    var smrL = BuildSide(-1, "L");
    report.AppendLine($"tassels built R={(smrR != null)} L={(smrL != null)}");

    // ---------- offscreen preview renders ----------
    try
    {
        var lightGO = new GameObject("__preview_light");
        lightGO.transform.SetParent(root, false);
        var l = lightGO.AddComponent<Light>();
        l.type = LightType.Directional;
        l.intensity = 1.05f;
        l.shadows = LightShadows.None;
        Vector3 lightDir = (-fwd * 0.7f - Vector3.up * 0.6f - rightDir * 0.35f).normalized;
        lightGO.transform.rotation = Quaternion.LookRotation(lightDir);

        var shots = new (Vector3 camPos, Vector3 lookAt, string file)[]
        {
            (new Vector3(pelvis.x, 0.78f, pelvis.z) + fwd * 2.6f, new Vector3(pelvis.x, 0.78f, pelvis.z), "preview_front.png"),
            (new Vector3(pelvis.x, 0.78f, pelvis.z) + fwd * 1.15f, new Vector3(pelvis.x, 0.62f, pelvis.z), "preview_hips.png"),
            (new Vector3(pelvis.x, 0.75f, pelvis.z) + rightDir * 2.4f, new Vector3(pelvis.x, 0.75f, pelvis.z), "preview_side.png")
        };
        int W = 640, H = 960;
        var rt = new RenderTexture(W, H, 24, RenderTextureFormat.ARGB32);
        foreach (var s in shots)
        {
            var camGO = new GameObject("__preview_cam");
            camGO.transform.SetParent(root, false);
            var cam = camGO.AddComponent<Camera>();
            cam.fieldOfView = 45f;
            cam.nearClipPlane = 0.01f;
            cam.farClipPlane = 50f;
            cam.clearFlags = CameraClearFlags.SolidColor;
            cam.backgroundColor = new Color(0.42f, 0.45f, 0.5f);
            cam.transform.position = s.camPos;
            cam.transform.LookAt(s.lookAt);
            cam.targetTexture = rt;
            cam.Render();
            RenderTexture.active = rt;
            var shot = new Texture2D(W, H, TextureFormat.RGBA32, false);
            shot.ReadPixels(new Rect(0, 0, W, H), 0, 0);
            shot.Apply();
            float bright = 0f;
            var px = shot.GetPixels32();
            for (int pI = 0; pI < px.Length; pI += 64) bright += px[pI].r;
            bright = bright / (px.Length / 64) / 255f;
            System.IO.File.WriteAllBytes("Temp/TasselWork/" + s.file, shot.EncodeToPNG());
            UnityEngine.Object.DestroyImmediate(shot);
            UnityEngine.Object.DestroyImmediate(camGO);
            report.AppendLine($"preview {s.file} avgBright={bright:F3}");
        }
        rt.Release();
        UnityEngine.Object.DestroyImmediate(rt);
        UnityEngine.Object.DestroyImmediate(lightGO);
    }
    catch (System.Exception rex)
    {
        report.AppendLine("RENDER_FAIL: " + rex.Message);
