// Play-mode verification of the skirt tassels on the live player instance.
var report = new System.Text.StringBuilder();
if (!EditorApplication.isPlaying)
    return "ERROR: not in play mode";

var player = GameObject.Find("PlayerHandle");
if (player == null) return "ERROR: PlayerHandle not found";
report.AppendLine("player found: " + player.name);

var tassels = player.GetComponentsInChildren<SkinnedMeshRenderer>(true);
int found = 0;
foreach (var smr in tassels)
{
    if (!smr.name.StartsWith("SkirtTassel")) continue;
    found++;
    var b = smr.bounds;
    report.AppendLine($"tassel {smr.name} active={smr.gameObject.activeInHierarchy} mesh={(smr.sharedMesh ? smr.sharedMesh.name : "null")} bones={smr.bones.Length} mat={(smr.sharedMaterial ? smr.sharedMaterial.name : "null")} boundsC=({b.center.x:F2},{b.center.y:F2},{b.center.z:F2}) boundsE=({b.extents.x:F2},{b.extents.y:F2},{b.extents.z:F2})");
    if (smr.bones.Length > 0 && smr.bones[0] != null)
    {
        var p = smr.bones[0].position; var q = smr.bones[0].eulerAngles;
        report.AppendLine($"  bone1 pos=({p.x:F3},{p.y:F3},{p.z:F3}) rot=({q.x:F0},{q.y:F0},{q.z:F0})");
    }
}
report.AppendLine("tassels on player: " + found);
if (found == 0) report.AppendLine("WARNING: no tassels found under PlayerHandle!");

var anim = player.GetComponentInChildren<Animator>();
if (anim != null)
    report.AppendLine("anim state: " + (anim.GetCurrentAnimatorStateInfo(0).shortNameHash) + " clip=" + (anim.GetCurrentAnimatorClipInfo(0).Length > 0 ? anim.GetCurrentAnimatorClipInfo(0)[0].clip.name : "?"));

// 1) game view capture
try
{
    var shot = ScreenCapture.CaptureScreenshotAsTexture();
    if (shot != null)
    {
        System.IO.File.WriteAllBytes("Temp/TasselWork/play_gameview.png", shot.EncodeToPNG());
        UnityEngine.Object.DestroyImmediate(shot);
        report.AppendLine("gameview captured");
    }
}
catch (System.Exception e) { report.AppendLine("gameview fail: " + e.Message); }

// 2) close-up render from a temp camera in front of the player
try
{
    Vector3 basePos = player.transform.position;
    Vector3 fwd = player.transform.forward; fwd.y = 0; fwd.Normalize();
    var camGO = new GameObject("__tassel_verify_cam");
    var cam = camGO.AddComponent<Camera>();
    cam.enabled = false;
    cam.fieldOfView = 40f;
    cam.nearClipPlane = 0.01f;
    cam.farClipPlane = 50f;
    cam.clearFlags = CameraClearFlags.SolidColor;
    cam.backgroundColor = new Color(0.42f, 0.45f, 0.5f);
    cam.transform.position = basePos + fwd * 1.9f + Vector3.up * 0.85f;
    cam.transform.LookAt(basePos + Vector3.up * 0.8f);
    int W = 720, H = 960;
    var rt = new RenderTexture(W, H, 24, RenderTextureFormat.ARGB32);
    cam.targetTexture = rt;
    cam.Render();
    RenderTexture.active = rt;
    var tex = new Texture2D(W, H, TextureFormat.RGBA32, false);
    tex.ReadPixels(new Rect(0, 0, W, H), 0, 0);
    tex.Apply();
    float bright = 0f; var px = tex.GetPixels32();
    for (int i = 0; i < px.Length; i += 64) bright += px[i].r;
    bright = bright / (px.Length / 64) / 255f;
    System.IO.File.WriteAllBytes("Temp/TasselWork/play_closeup.png", tex.EncodeToPNG());
    UnityEngine.Object.DestroyImmediate(tex);
    rt.Release();
    UnityEngine.Object.DestroyImmediate(rt);
    UnityEngine.Object.DestroyImmediate(camGO);
    report.AppendLine("closeup captured avgBright=" + bright.ToString("F3"));
}
catch (System.Exception e) { report.AppendLine("closeup fail: " + e.Message); }

return report.ToString();

const fs = require('fs');
const script = fs.readFileSync('K:\\0.GameDev\\DarkSouls\\Temp\\TasselWork\\verify_play.csx', 'utf8');
module.exports = {
  type: "execute_csharp_script",
  params: {
    script: script,
    summary: "Verify tassels on live player instance and capture game view + close-up renders",
    execution_mode: "play",
    capture_logs: true
  }
};

