// Build two miHoYo-style wide skirt-tassel drapes on Kazuko, with same-family edge trim.
// Rigid now (bone chains under Root_M), cloth-sim-ready later via Magica Cloth BoneCloth.
var prefabPath = "Assets/Prefabs/Kazuko.prefab";
if (EditorApplication.isPlayingOrWillChangePlaymode)
    return "ERROR: Unity is in play mode, cannot modify prefab.";

var contents = PrefabUtility.LoadPrefabContents(prefabPath);
var report = new System.Text.StringBuilder();
try
{
    Transform Find(string n)
    {
        foreach (var t in contents.GetComponentsInChildren<Transform>(true))
            if (t.name == n) return t;
        return null;
    }

    var hipL = Find("Hip_L");
    var hipR = Find("Hip_R");
    var eyeL = Find("Eye1_L");
    var eyeR = Find("Eye1_R");
    var headM = Find("Head_M");
    var rootM = Find("Root_M");
    var root = contents.transform;
    if (hipL == null || hipR == null || rootM == null || eyeL == null || eyeR == null)
        return "ERROR: key bones not found";

    Vector3 pelvis = (hipL.position + hipR.position) * 0.5f;

    Vector3 fwd = ((eyeL.position + eyeR.position) * 0.5f - (headM != null ? headM.position : pelvis));
    fwd.y = 0f;
    fwd = fwd.sqrMagnitude > 1e-8f ? fwd.normalized : Vector3.forward;
    Vector3 rightDir = Vector3.Cross(Vector3.up, fwd).normalized;
    report.AppendLine($"pelvis=({pelvis.x:F3},{pelvis.y:F3},{pelvis.z:F3}) fwd=({fwd.x:F3},{fwd.y:F3},{fwd.z:F3}) right=({rightDir.x:F3},{rightDir.y:F3},{rightDir.z:F3})");

    // ---------- texture: cloth base + same-family trim (edge binding) ----------
    int TW = 256, TH = 512;
    var tex = new Texture2D(TW, TH, TextureFormat.RGBA32, false);
    Color baseC = new Color(0.723f, 0.672f, 0.589f);
    Color trimC = new Color(0.208f, 0.166f, 0.154f);
    Color accentC = new Color(0.85f, 0.80f, 0.68f);
    for (int y = 0; y < TH; y++)
    {
        float v = (float)y / (TH - 1);
        for (int x = 0; x < TW; x++)
        {
            float u = (float)x / (TW - 1);
            Color c;
            bool edge = u < 0.045f || u > 0.955f;
            bool edgeAcc = !edge && (u < 0.075f || u > 0.925f);
            bool top = v > 0.96f;
            bool topAcc = !top && v > 0.92f;
            bool bot = v < 0.09f;
            bool botAcc = !bot && v < 0.155f;
            if (edge || top || bot) c = trimC;
            else if (edgeAcc || topAcc || botAcc) c = accentC;
            else
            {
                float weave = ((x / 4) % 2 == 0) ? 1.0f : 0.96f;
                float grad = Mathf.Lerp(0.97f, 1.02f, v);
                c = baseC * (weave * grad);
            }
            tex.SetPixel(x, y, c);
        }
    }
    tex.Apply();
    string texPath = "Assets/Textures/Kazuko/Kazuko_SkirtTassel.png";
    System.IO.File.WriteAllBytes(texPath, tex.EncodeToPNG());
