    AssetDatabase.ImportAsset(texPath);
    var importer = (TextureImporter)AssetImporter.GetAtPath(texPath);
    if (importer != null)
    {
        importer.sRGBTexture = true;
        importer.mipmapEnabled = true;
        importer.wrapMode = TextureWrapMode.Repeat;
        importer.SaveAndReimport();
    }
    var texAsset = AssetDatabase.LoadAssetAtPath<Texture2D>(texPath);
    if (texAsset == null) return "ERROR: texture import failed";
    report.AppendLine("tex OK " + texPath);

    // ---------- material: same toon shader/params as kazuko_cloth ----------
    var cloth = AssetDatabase.LoadAssetAtPath<Material>("Assets/Arts/Materials/kazuko/kazuko_cloth.mat");
    if (cloth == null) return "ERROR: kazuko_cloth.mat not found";
    string matPath = "Assets/Arts/Materials/kazuko/kazuko_skirt_tassel.mat";
    if (AssetDatabase.LoadAssetAtPath<Material>(matPath) != null) AssetDatabase.DeleteAsset(matPath);
    var mat = new Material(cloth.shader);
    mat.CopyPropertiesFromMaterial(cloth);
    mat.SetTexture("_MainTex", texAsset);
    mat.SetColor("_MainColor", Color.white); // texture carries the color
    mat.name = "kazuko_skirt_tassel";
    AssetDatabase.CreateAsset(mat, matPath);
    report.AppendLine("mat OK " + matPath);

    // ---------- remove previous tassel objects (idempotent rebuild) ----------
    var toDestroy = new System.Collections.Generic.List<GameObject>();
    foreach (var t in contents.GetComponentsInChildren<Transform>(true))
        if (t.name.StartsWith("SkirtTassel")) toDestroy.Add(t.gameObject);
    foreach (var g in toDestroy) UnityEngine.Object.DestroyImmediate(g);
    if (toDestroy.Count > 0) report.AppendLine("removed " + toDestroy.Count + " old tassel objects");

    // ---------- geometry params ----------
    float topY = 0.985f, botY = 0.24f, toothRise = 0.07f;
    int rows = 13, cols = 9;

    // runtime ground-truth test for triangle winding convention
    bool crossIsFront;
    {
        var testMesh = new Mesh();
        testMesh.vertices = new Vector3[] { new Vector3(0, 0, 0), new Vector3(1, 0, 0), new Vector3(0, 1, 0) };
        testMesh.triangles = new int[] { 0, 1, 2 };
        testMesh.RecalculateNormals();
        crossIsFront = testMesh.normals[0].z > 0f;
        UnityEngine.Object.DestroyImmediate(testMesh);
    }
    report.AppendLine("winding crossIsFront=" + crossIsFront);

    SkinnedMeshRenderer BuildSide(int sideSign, string sideName)
    {
        Vector3 sideDir = rightDir * sideSign;
        Vector3 normal = (sideDir * Mathf.Cos(15f * Mathf.Deg2Rad) + fwd * Mathf.Sin(15f * Mathf.Deg2Rad)).normalized;
        Vector3 binorm = Vector3.Cross(Vector3.up, normal).normalized;

        Vector3 CenterAt(float t)
        {
            float lat = 0.14f, fw = 0.045f;
            float tk = Mathf.InverseLerp(0.833f, 1f, t);
            lat = Mathf.Lerp(lat, 0.085f, tk);
            fw = Mathf.Lerp(fw, 0.02f, tk);
            Vector3 c = pelvis + sideDir * lat + fwd * fw;
            c.y = Mathf.Lerp(botY, topY, t);
            return c;
        }
        float HalfW(float t) { return Mathf.Lerp(0.10f, 0.085f, t); }

        // vertices (world space)
        var verts = new System.Collections.Generic.List<Vector3>();
        var uvs = new System.Collections.Generic.List<Vector2>();
        for (int i = 0; i < rows; i++)
        {
            float t = (float)i / (rows - 1);
            Vector3 c = CenterAt(t);
            float hw = HalfW(t);
            for (int cI = 0; cI < cols; cI++)
            {
                float u = (float)cI / (cols - 1);
                Vector3 p = c + binorm * ((u * 2f - 1f) * hw);
                float k = u * 2f - 1f;
                p += normal * (0.012f * (1f - k * k)); // slight convexity
                if (i == 0 && (cI % 2) == 1) p += Vector3.up * toothRise; // fringe teeth
                verts.Add(p);
                uvs.Add(new Vector2(u, t));
            }
        }
        var tris = new System.Collections.Generic.List<int>();
        for (int i = 0; i < rows - 1; i++)
        {
            for (int cI = 0; cI < cols - 1; cI++)
            {
                int i0 = i * cols + cI, i1 = i * cols + cI + 1, i2 = (i + 1) * cols + cI + 1, i3 = (i + 1) * cols + cI;
                if (crossIsFront) { tris.AddRange(new int[] { i0, i1, i2, i0, i2, i3 }); }
                else { tris.AddRange(new int[] { i0, i2, i1, i0, i3, i2 }); }
            }
        }
