        {
            float f = (1f - uvs[vi].y) * 3f;
            int b0 = Mathf.Clamp(Mathf.FloorToInt(f), 0, 3);
            int b1 = Mathf.Min(b0 + 1, 3);
            float w1 = Mathf.Clamp(f - b0, 0f, 1f);
            bw[vi] = new BoneWeight { boneIndex0 = b0, weight0 = 1f - w1, boneIndex1 = b1, weight1 = w1 };
