    // ---------- measure the character's rear silhouette (skirt armor + body) ----------
    SkinnedMeshRenderer FindSmr(string meshName)
    {
        foreach (var r in contents.GetComponentsInChildren<SkinnedMeshRenderer>(true))
            if (r.sharedMesh != null && r.sharedMesh.name == meshName) return r;
        return null;
    }
    var armorSmr = FindSmr("Kasuko_armor");
    var skinSmr = FindSmr("Kazuko_skin");
    if (armorSmr == null || skinSmr == null) return "ERROR: armor/skin SMR not found";

    const float bandStep = 0.05f;
    int bandCount = 26; // y 0.15 .. 1.45
    var rearBack = new float[bandCount];
    float armorRearMaxY = 0f, armorRearMinY = 10f, armorRearMaxBack = 0f;
    void MeasureRear(SkinnedMeshRenderer smr)
    {
        var mesh = smr.sharedMesh;
        var vs = mesh.vertices;
        var l2w = smr.transform.localToWorldMatrix;
        foreach (var v in vs)
        {
            Vector3 w = l2w.MultiplyPoint3x4(v);
            Vector3 rel = w - pelvis;
            float back = -Vector3.Dot(rel, fwd);
            float latv = Vector3.Dot(rel, rightDir);
            if (back <= 0f || Mathf.Abs(latv) > 0.18f) continue;
            int bi = Mathf.Clamp(Mathf.FloorToInt((w.y - 0.15f) / bandStep), 0, bandCount - 1);
            if (back > rearBack[bi]) rearBack[bi] = back;
            if (smr == armorSmr)
            {
                if (w.y > armorRearMaxY) armorRearMaxY = w.y;
                if (w.y < armorRearMinY) armorRearMinY = w.y;
                if (back > armorRearMaxBack) armorRearMaxBack = back;
            }
        }
    }
    MeasureRear(armorSmr);
    MeasureRear(skinSmr);
    // light smoothing
    for (int pass = 0; pass < 2; pass++)
    {
        var s = new float[bandCount];
        for (int i = 0; i < bandCount; i++)
        {
            float a = rearBack[Mathf.Max(0, i - 1)], b = rearBack[i], c = rearBack[Mathf.Min(bandCount - 1, i + 1)];
            s[i] = (a + b + c) / 3f;
        }
        rearBack = s;
    }
    float RearBackAt(float y)
    {
        float f = Mathf.Clamp((y - 0.15f) / bandStep, 0f, bandCount - 1.001f);
        int i = Mathf.FloorToInt(f);
        return Mathf.Lerp(rearBack[i], rearBack[Mathf.Min(i + 1, bandCount - 1)], f - i);
