// ---------- measure the character's rear silhouette (skirt armor + body), per height band ----------
SkinnedMeshRenderer FindSmr(string meshName)
{
    foreach (var r in contents.GetComponentsInChildren<SkinnedMeshRenderer>(true))
        if (r.sharedMesh != null && r.sharedMesh.name == meshName) return r;
    return null;
}
var armorSmr = FindSmr("Kasuko_armor");
var skinSmr = FindSmr("Kazuko_skin");
if (armorSmr == null || skinSmr == null) return "ERROR: Kasuko_armor / Kazuko_skin SMR not found";

const float bandStep = 0.05f;
int bandCount = 26; // covers y 0.15 .. 1.45
var rearBack = new float[bandCount];
float armorRearMaxY = 0f;
void MeasureRear(SkinnedMeshRenderer smr)
{
    var l2w = smr.transform.localToWorldMatrix;
    foreach (var v in smr.sharedMesh.vertices)
    {
        Vector3 w = l2w.MultiplyPoint3x4(v);
        Vector3 rel = w - pelvis;
        float back = -Vector3.Dot(rel, fwd);
        float latv = Vector3.Dot(rel, rightDir);
        if (back <= 0f || Mathf.Abs(latv) > 0.18f) continue;
        int bi = Mathf.Clamp(Mathf.FloorToInt((w.y - 0.15f) / bandStep), 0, bandCount - 1);
        if (back > rearBack[bi]) rearBack[bi] = back;
        if (smr == armorSmr && w.y > armorRearMaxY) armorRearMaxY = w.y;
    }
}
MeasureRear(armorSmr);
MeasureRear(skinSmr);
for (int pass = 0; pass < 2; pass++) // light smoothing so the ribbon path doesn't wobble with mesh bumps
{
    var s = new float[bandCount];
    for (int i = 0; i < bandCount; i++)
        s[i] = (rearBack[Mathf.Max(0, i - 1)] + rearBack[i] + rearBack[Mathf.Min(bandCount - 1, i + 1)]) / 3f;
    rearBack = s;
}
float RearBackAt(float y)
{
    float f = Mathf.Clamp((y - 0.15f) / bandStep, 0f, bandCount - 1.001f);
    int i = Mathf.FloorToInt(f);
    return Mathf.Lerp(rearBack[i], rearBack[Mathf.Min(i + 1, bandCount - 1)], f - i);
}
float topY = Mathf.Clamp(armorRearMaxY, 1.02f, 1.14f) + 0.03f; // ribbon belt sits just above the skirt armor's rear top
var prof = new System.Text.StringBuilder();
for (int i = 0; i < bandCount; i++) if (rearBack[i] > 0.01f) prof.Append((0.15f + i * bandStep).ToString("F2") + ":" + rearBack[i].ToString("F3") + " ");
report.AppendLine("rear profile y:back  " + prof.ToString());
report.AppendLine($"armorRearMaxY={armorRearMaxY:F3} topY={topY:F3} rearAt(topY)={RearBackAt(topY):F3} rearAt(0.80)={RearBackAt(0.80f):F3}");

