var report = new System.Text.StringBuilder();
report.AppendLine("isPlaying=" + EditorApplication.isPlaying);

for (int si = 0; si < EditorSceneManager.sceneCount; si++)
{
    var scene = EditorSceneManager.GetSceneAt(si);
    if (!scene.isLoaded) continue;
    report.AppendLine("scene: " + scene.path);
    foreach (var root in scene.GetRootGameObjects())
    {
        MagicaCloth2.MagicaCloth[] comps = null;
        try { comps = root.GetComponentsInChildren<MagicaCloth2.MagicaCloth>(true); } catch { }
        if (comps == null) continue;
        foreach (var mc in comps)
        {
            var ser = MagicaCloth2.Serialization.MagicaClothSerializeDataUtility.GetSerializeData(mc);
            report.AppendLine($"  MC2 '{mc.name}' on GO='{mc.gameObject.name}' path='{GetPath(mc.transform)}' clothType={ser.ClothType} rootBones={(ser.RootBoneList != null ? ser.RootBoneList.Count : -1)}");
            if (ser.RootBoneList != null)
                foreach (var rb in ser.RootBoneList)
                    report.AppendLine("    rootBone: " + (rb ? rb.name + " @ " + GetPath(rb.transform) : "<missing>"));
        }
    }
}

// also check the prefab asset itself
var prefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Kazuko.prefab");
if (prefab != null)
{
    var comps = prefab.GetComponentsInChildren<MagicaCloth2.MagicaCloth>(true);
    report.AppendLine("prefab MC2 count: " + (comps != null ? comps.Length : -1));
    if (comps != null)
        foreach (var mc in comps)
            report.AppendLine("  prefab MC2 '" + mc.name + "' on " + mc.gameObject.name);
}

string GetPath(Transform t)
{
    var p = t.name;
    while (t.parent != null) { t = t.parent; p = t.name + "/" + p; }
    return p;
}

return report.ToString();

