args.content:
// Twin anti-gravity back ribbons on Kazuko: big crinoline-style side arc, lifted pencil-tip tail,
// 5-bone chains for cloth sway, twisting panel frame (faces back at top, sideways at tail).
var prefabPath = "Assets/Prefabs/Kazuko.prefab";
if (EditorApplication.isPlayingOrWillChangePlaymode)
    return "ERROR: Unity is in play mode, cannot modify prefab.";

var contents = PrefabUtility.LoadPrefabContents(prefabPath);
var report = new System.Text.StringBuilder();
try
{
    Transform Find(string n)
    {
        foreach (var t in contents.GetComponentsInChildren<Transform>(true))
            if (t.name == n) return t;
        return null;
    }

    var hipL = Find("Hip_L");
    var hipR = Find("Hip_R");
    var eyeL = Find("Eye1_L");
    var eyeR = Find("Eye1_R");
    var headM = Find("Head_M");
    var rootM = Find("Root_M");
    var root = contents.transform;
    if (hipL == null || hipR == null || rootM == null || eyeL == null || eyeR == null)
        return "ERROR: key bones not found";

    Vector3 pelvis = (hipL.position + hipR.position) * 0.5f;

    Vector3 fwd = ((eyeL.position + eyeR.position) * 0.5f - (headM != null ? headM.position : pelvis));
    fwd.y = 0f;
    fwd = fwd.sqrMagnitude > 1e-8f ? fwd.normalized : Vector3.forward;
    Vector3 rightDir = Vector3.Cross(Vector3.up, fwd).normalized;
    report.AppendLine($"pelvis=({pelvis.x:F3},{pelvis.y:F3},{pelvis.z:F3}) fwd=({fwd.x:F3},{fwd.y:F3},{fwd.z:F3}) right=({rightDir.x:F3},{rightDir.y:F3},{rightDir.z:F3})");

    // ---------- measure the character's rear silhouette (skirt armor + body), per height band ----------
    SkinnedMeshRenderer FindSmr(string meshName)
    {
        foreach (var r in contents.GetComponentsInChildren<SkinnedMeshRenderer>(true))
            if (r.sharedMesh != null && r.sharedMesh.name == meshName) return r;
        return null;
    }
    var armorSmr = FindSmr("Kasuko_armor");
    var skinSmr = FindSmr("Kazuko_skin");
    if (armorSmr == null || skinSmr == null) return "ERROR: Kasuko_armor / Kazuko_skin SMR not found";

    const float bandStep = 0.05f;
    int bandCount = 26; // covers y 0.15 .. 1.45
    var rearBack = new float[bandCount];
    var armorBack = new float[bandCount];
    void MeasureRear(SkinnedMeshRenderer smr)
    {
        var l2w = smr.transform.localToWorldMatrix;
        bool isArmor = smr == armorSmr;
        foreach (var v in smr.sharedMesh.vertices)
        {
            Vector3 w = l2w.MultiplyPoint3x4(v);
            Vector3 rel = w - pelvis;
            float back = -Vector3.Dot(rel, fwd);
            float latv = Vector3.Dot(rel, rightDir);
            if (back <= 0f || Mathf.Abs(latv) > 0.18f) continue;
            int bi = Mathf.Clamp(Mathf.FloorToInt((w.y - 0.15f) / bandStep), 0, bandCount - 1);
            if (back > rearBack[bi]) rearBack[bi] = back;
            if (isArmor && back > armorBack[bi]) armorBack[bi] = back;
        }
    }
    MeasureRear(armorSmr);
    MeasureRear(skinSmr);
    for (int pass = 0; pass < 2; pass++)
    {
        var s = new float[bandCount];
        var s2 = new float[bandCount];
        for (int i = 0; i < bandCount; i++)
        {
            s[i] = (rearBack[Mathf.Max(0, i - 1)] + rearBack[i] + rearBack[Mathf.Min(bandCount - 1, i + 1)]) / 3f;
            s2[i] = (armorBack[Mathf.Max(0, i - 1)] + armorBack[i] + armorBack[Mathf.Min(bandCount - 1, i + 1)]) / 3f;
        }
        rearBack = s;
        armorBack = s2;
    }
    float BandAt(float[] a, float y)
    {
        float f = Mathf.Clamp((y - 0.15f) / bandStep, 0f, bandCount - 1.001f);
        int i = Mathf.FloorToInt(f);
        return Mathf.Lerp(a[i], a[Mathf.Min(i + 1, bandCount - 1)], f - i);
    }
    float RearBackAt(float y) => BandAt(rearBack, y);
    float skirtTopY = 0.95f;
    for (int i = bandCount - 1; i >= 0; i--)
        if (armorBack[i] > 0.11f) { skirtTopY = 0.15f + (i + 1) * bandStep; break; }
    float topY = Mathf.Clamp(skirtTopY + 0.025f, 1.00f, 1.12f); // ribbon belt sits just above the skirt's rear top
    report.AppendLine($"skirtTopY={skirtTopY:F3} topY={topY:F3} rearAt(topY)={RearBackAt(topY):F3}");

    // ---------- texture: cloth base + same-family trim (edge binding) ----------
    int TW = 256, TH = 512;
    var tex = new Texture2D(TW, TH, TextureFormat.RGBA32, false);
    Color baseC = new Color(0.723f, 0.672f, 0.589f);
    Color trimC = new Color(0.208f, 0.166f, 0.154f);
    Color accentC = new Color(0.85f, 0.80f, 0.68f);
    for (int y = 0; y < TH; y++)
    {
        float v = (float)y / (TH - 1);
        for (int x = 0; x < TW; x++)
        {
            float u = (float)x / (TW - 1);
            Color c;
            bool edge = u < 0.045f || u > 0.955f;
            bool edgeAcc = !edge && (u < 0.075f || u > 0.925f);
            bool top = v > 0.96f;
            bool topAcc = !top && v > 0.92f;
            bool bot = v < 0.19f;      // whole pencil-tip cone in dark trim (tipT ~ 0.15)
            bool botAcc = !bot && v < 0.26f;
            if (edge || top || bot) c = trimC;
            else if (edgeAcc || topAcc || botAcc) c = accentC;
            else
            {
                float weave = ((x / 4) % 2 == 0) ? 1.0f : 0.96f;
                float grad = Mathf.Lerp(0.97f, 1.02f, v);
                c = baseC * (weave * grad);
            }
            tex.SetPixel(x, y, c);
        }
    }
    tex.Apply();
    string texPath = "Assets/Textures/Kazuko/Kazuko_SkirtTassel.png";
    System.IO.File.WriteAllBytes(texPath, tex.EncodeToPNG());
    UnityEngine.Object.DestroyImmediate(tex);
    AssetDatabase.ImportAsset(texPath);
    var importer = (TextureImporter)AssetImporter.GetAtPath(texPath);
    if (importer != null)
    {
        importer.sRGBTexture = true;
        importer.mipmapEnabled = true;
        importer.wrapMode = TextureWrapMode.Repeat;
        importer.SaveAndReimport();
    }
    var texAsset = AssetDatabase.LoadAssetAtPath<Texture2D>(texPath);
    if (texAsset == null) return "ERROR: texture import failed";
    report.AppendLine("tex OK " + texPath);

    // ---------- material: same toon shader/params as kazuko_cloth ----------
    var cloth = AssetDatabase.LoadAssetAtPath<Material>("Assets/Arts/Materials/kazuko/kazuko_cloth.mat");
    if (cloth == null) return "ERROR: kazuko_cloth.mat not found";
    string matPath = "Assets/Arts/Materials/kazuko/kazuko_skirt_tassel.mat";
    if (AssetDatabase.LoadAssetAtPath<Material>(matPath) != null) AssetDatabase.DeleteAsset(matPath);
    var mat = new Material(cloth.shader);
    mat.CopyPropertiesFromMaterial(cloth);
    mat.SetTexture("_MainTex", texAsset);
    mat.SetColor("_MainColor", Color.white); // texture carries the color
    mat.name = "kazuko_skirt_tassel";
    AssetDatabase.CreateAsset(mat, matPath);
    report.AppendLine("mat OK " + matPath);

    // ---------- remove previous tassel objects (idempotent rebuild) ----------
    var toDestroy = new System.Collections.Generic.List<GameObject>();
    foreach (var t in contents.GetComponentsInChildren<Transform>(true))
        if (t.name.StartsWith("SkirtTassel")) toDestroy.Add(t.gameObject);
    foreach (var g in toDestroy) UnityEngine.Object.DestroyImmediate(g);
    if (toDestroy.Count > 0) report.AppendLine("removed " + toDestroy.Count + " old tassel objects");

    // ---------- geometry: anti-gravity crinoline arc (cubic Bezier in the y/back side-plane) ----------
    int rows = 13, cols = 5;
    float tipT = 0.15f;                                       // last 15% of the arc = pencil-tip cone
    float bezY0 = topY, bezB0 = RearBackAt(topY) + 0.03f;     // start: just above the skirt's rear top edge
    float bezY1 = topY - 0.10f, bezB1 = 0.30f;                // sweep back over the skirt
    float bezY2 = 0.28f, bezB2 = 0.62f;                        // deep belly (the invisible giant crinoline)
    float bezY3 = 0.58f, bezB3 = 0.48f;                       // lifted tail tip (anti-gravity)

    // runtime ground-truth test for triangle winding convention
    bool crossIsFront;
    {
        var testMesh = new Mesh();
        testMesh.vertices = new Vector3[] { new Vector3(0, 0, 0), new Vector3(1, 0, 0), new Vector3(0, 1, 0) };
        testMesh.triangles = new int[] { 0, 1, 2 };
        testMesh.RecalculateNormals();
        crossIsFront = testMesh.normals[0].z > 0f;
        UnityEngine.Object.DestroyImmediate(testMesh);
    }
    report.AppendLine("winding crossIsFront=" + crossIsFront);

    SkinnedMeshRenderer BuildSide(int sideSign, string sideName)
    {
        Vector3 sideDir = rightDir * sideSign;

        Vector3 CenterAt(float t)
        {
            // t: 1 = top (at the skirt's rear top edge), 0 = lifted tail tip
            float u = 1f - t;
            float w0 = (1f - u) * (1f - u) * (1f - u);
            float w1 = 3f * (1f - u) * (1f - u) * u;
            float w2 = 3f * (1f - u) * u * u;
            float w3 = u * u * u;
            float y = w0 * bezY0 + w1 * bezY1 + w2 * bezY2 + w3 * bezY3;
            float back = w0 * bezB0 + w1 * bezB1 + w2 * bezB2 + w3 * bezB3;
            float lat = Mathf.Lerp(0.088f, 0.068f, t); // slight divergence toward the tail
            Vector3 c = pelvis - fwd * back + sideDir * lat;
            c.y = y;
            return c;
        }
        Vector3 TangentAt(float t)
        {
            const float eps = 0.008f;
            Vector3 d = CenterAt(Mathf.Clamp01(t + eps)) - CenterAt(Mathf.Clamp01(t - eps));
            return d.sqrMagnitude > 1e-10f ? d.normalized : Vector3.up;
        }
        Vector3 FaceAt(float t)
        {
            // twist: face backward at the top (belt visible from behind), sideways at the tail
            // (the big arc reads from the side view), always kept perpendicular to the arc tangent
            float twist = Mathf.Clamp01(1f - t);
            Vector3 fanBack = (-fwd * Mathf.Cos(15f * Mathf.Deg2Rad) + sideDir * Mathf.Sin(15f * Mathf.Deg2Rad)).normalized;
            Vector3 fanSide = (sideDir * Mathf.Cos(20f * Mathf.Deg2Rad) - fwd * Mathf.Sin(20f * Mathf.Deg2Rad)).normalized;
            Vector3 d = ((1f - twist) * fanBack + twist * fanSide).normalized;
            Vector3 tg = TangentAt(t);
            d = d - tg * Vector3.Dot(d, tg);
            return d.sqrMagnitude > 1e-10f ? d.normalized : fanBack;
        }
        float HalfW(float t) { return Mathf.Lerp(0.048f, 0.042f, t); }

        // vertices (world space): rows span the shaft; the pencil tip vertex is added after the grid
        var verts = new System.Collections.Generic.List<Vector3>();
        var uvs = new System.Collections.Generic.List<Vector2>();
        var nrm = new System.Collections.Generic.List<Vector3>();
        for (int i = 0; i < rows; i++)
        {
            float t = Mathf.Lerp(tipT, 1f, (float)i / (rows - 1));
            Vector3 c = CenterAt(t);
            Vector3 F = FaceAt(t);
            Vector3 W = Vector3.Cross(F, TangentAt(t)).normalized;
            float hw = HalfW(t);
            for (int cI = 0; cI < cols; cI++)
            {
                float u = (float)cI / (cols - 1);
                float k = u * 2f - 1f;
                Vector3 p = c + W * (k * hw) + F * (0.012f * (1f - k * k)); // slight convexity
                verts.Add(p);
                uvs.Add(new Vector2(u, t));
                nrm.Add(F);
            }
        }

        // grid winding decided from the actual frame (conventions may flip with the twisted layout)
        bool gridStraight = Vector3.Dot(Vector3.Cross(verts[1] - verts[0], verts[cols + 1] - verts[0]), nrm[0]) >= 0f;
        bool useGridStraight = gridStraight == crossIsFront;

        var tris = new System.Collections.Generic.List<int>();
        for (int i = 0; i < rows - 1; i++)
        {
            for (int cI = 0; cI < cols - 1; cI++)
            {
                int i0 = i * cols + cI, i1 = i * cols + cI + 1, i2 = (i + 1) * cols + cI + 1, i3 = (i + 1) * cols + cI;
                if (useGridStraight) { tris.AddRange(new int[] { i0, i1, i2, i0, i2, i3 }); }
                else { tris.AddRange(new int[] { i0, i2, i1, i0, i3, i2 }); }
            }
        }

        // pencil tip: one vertex at the arc's end, fanned onto the bottom shaft row
        int tipIdx = verts.Count;
        Vector3 tipPos = CenterAt(0f);
        Vector3 tipNrm = FaceAt(0f);
        verts.Add(tipPos);
        uvs.Add(new Vector2(0.5f, 0f));
        nrm.Add(tipNrm);
        bool fanStraight = Vector3.Dot(Vector3.Cross(verts[1] - verts[0], tipPos - verts[0]), nrm[0]) >= 0f;
        bool useFanStraight = fanStraight == crossIsFront;
        for (int cI = 0; cI < cols - 1; cI++)
        {
            if (useFanStraight) { tris.AddRange(new int[] { cI, cI + 1, tipIdx }); }
            else { tris.AddRange(new int[] { cI, tipIdx, cI + 1 }); }
        }

        // double-sided back copy
        int vCount = verts.Count;
        for (int vi = 0; vi < vCount; vi++) { verts.Add(verts[vi]); uvs.Add(uvs[vi]); nrm.Add(-nrm[vi]); }
        int triCount = tris.Count;
        for (int ti = 0; ti < triCount; ti += 3)
            tris.AddRange(new int[] { vCount + tris[ti + 2], vCount + tris[ti + 1], vCount + tris[ti] });

        // bone chain (5 bones along the arc, for Magica Cloth BoneCloth sway)
        var boneTs = new Transform[5];
        Transform parentB = rootM;
        for (int b = 0; b < 5; b++)
        {
            var bgo = new GameObject("SkirtTasselBone_" + sideName + (b + 1));
            bgo.transform.SetParent(parentB, false);
            bgo.transform.position = CenterAt(1f - b / 4f);
            bgo.transform.rotation = Quaternion.identity;
            parentB = bgo.transform;
            boneTs[b] = bgo.transform;
        }

        // tassel GO (identity local under prefab root)
        var tgo = new GameObject("SkirtTassel_" + sideName);
        tgo.transform.SetParent(root, false);
        Matrix4x4 go2world = tgo.transform.localToWorldMatrix;

        for (int vi = 0; vi < verts.Count; vi++) verts[vi] = tgo.transform.InverseTransformPoint(verts[vi]);

        var mesh = new Mesh();
        mesh.name = "Kazuko_SkirtTassel_" + sideName;
        mesh.SetVertices(verts);
        mesh.SetUVs(0, uvs);
        mesh.SetNormals(nrm);
        mesh.SetTriangles(tris, 0);

        var binds = new Matrix4x4[5];
        for (int b = 0; b < 5; b++) binds[b] = boneTs[b].worldToLocalMatrix * go2world;
        mesh.bindposes = binds;
        var bw = new BoneWeight[verts.Count];
        for (int vi = 0; vi < verts.Count; vi++)
        {
            float f = (1f - uvs[vi].y) * 4f;
            int b0 = Mathf.Clamp(Mathf.FloorToInt(f), 0, 4);
            int b1 = Mathf.Min(b0 + 1, 4);
            float w1 = Mathf.Clamp(f - b0, 0f, 1f);
            bw[vi] = new BoneWeight { boneIndex0 = b0, weight0 = 1f - w1, boneIndex1 = b1, weight1 = w1 };
        }
        mesh.boneWeights = bw;
        mesh.RecalculateBounds();

        string meshPath = "Assets/Arts/Models/Main Characters/kazuko/Kazuko_SkirtTassel_" + sideName + ".asset";
        if (AssetDatabase.LoadAssetAtPath<Mesh>(meshPath) != null) AssetDatabase.DeleteAsset(meshPath);
        AssetDatabase.CreateAsset(mesh, meshPath);
        report.AppendLine("mesh OK " + meshPath + " verts=" + verts.Count);

        var smr = tgo.AddComponent<SkinnedMeshRenderer>();
        smr.sharedMesh = mesh;
        smr.bones = boneTs;
        smr.rootBone = boneTs[0];
        smr.sharedMaterial = mat;
        smr.updateWhenOffscreen = true;
        smr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.On;
        smr.receiveShadows = true;
        smr.localBounds = new Bounds(mesh.bounds.center, mesh.bounds.size * 1.3f);
        return smr;
    }

    var smrR = BuildSide(+1, "R");
    var smrL = BuildSide(-1, "L");
    report.AppendLine($"tassels built R={(smrR != null)} L={(smrL != null)}");
    report.AppendLine($"arc: top({bezY0:F2},{bezB0:F2}) belly-ctrl({bezY2:F2},{bezB2:F2}) tip({bezY3:F2},{bezB3:F2})");

    PrefabUtility.SaveAsPrefabAsset(contents, prefabPath);
    AssetDatabase.SaveAssets();
    report.AppendLine("PREFAB_SAVED");
    return report.ToString();
}
finally
{
    PrefabUtility.UnloadPrefabContents(contents);
}

