// Ground-truth check: print the built tassel arc positions from the prefab asset.
var prefabPath = "Assets/Prefabs/Kazuko.prefab";
var contents = PrefabUtility.LoadPrefabContents(prefabPath);
try
{
    var report = new System.Text.StringBuilder();
    foreach (var smr in contents.GetComponentsInChildren<SkinnedMeshRenderer>(true))
    {
        if (!smr.name.StartsWith("SkirtTassel")) continue;
        var m = smr.sharedMesh;
        report.AppendLine(smr.name + " mesh=" + (m ? m.name : "null") + " verts=" + m.vertexCount + " mat=" + (smr.sharedMaterial ? smr.sharedMaterial.name : "null"));
        if (smr.sharedMaterial != null)
            report.AppendLine("  _MainTex=" + (smr.sharedMaterial.GetTexture("_MainTex") ? smr.sharedMaterial.GetTexture("_MainTex").name : "NULL") + " _MainColor=" + smr.sharedMaterial.GetColor("_MainColor"));
        var l2w = smr.transform.localToWorldMatrix;
        // rows: 13 rows x 5 cols, then tip vertex at index 65 (before the back copy at 66+)
        int rows = 13, cols = 5;
        var vs = m.vertices;
        for (int rowIdx = 0; rowIdx < rows; rowIdx += 3) // sample rows 0,3,6,9,12
        {
            int vi = rowIdx * cols + 2; // center column
            Vector3 w = l2w.MultiplyPoint3x4(vs[vi]);
            report.AppendLine($"  row{rowIdx} (t={(rowIdx/(float)(rows-1)):F2}) center=({w.x:F3},{w.y:F3},{w.z:F3})");
        }
        Vector3 tipW = l2w.MultiplyPoint3x4(vs[65]);
        report.AppendLine($"  TIP vertex=({tipW.x:F3},{tipW.y:F3},{tipW.z:F3})");
        var b = m.bounds;
        report.AppendLine($"  mesh bounds c=({b.center.x:F2},{b.center.y:F2},{b.center.z:F2}) e=({b.extents.x:F2},{b.extents.y:F2},{b.extents.z:F2})");
        report.AppendLine("  bones=" + smr.bones.Length);
        for (int bi = 0; bi < smr.bones.Length; bi++)
        {
            var bp = smr.bones[bi] ? smr.bones[bi].position : Vector3.zero;
            report.AppendLine($"    bone{bi} '{(smr.bones[bi] ? smr.bones[bi].name : "null")}' pos=({bp.x:F3},{bp.y:F3},{bp.z:F3})");
        }
    }
    return report.ToString();
}
finally { PrefabUtility.UnloadPrefabContents(contents); }

