// White puffy lantern bloomers under the skirt, over the bikini (anti-peek, gacha-style).
// Data-driven: measures skin+bikini cross-sections, lofts a peanut shell (hip ellipse + two
// thigh lobes), closes each leg with a domed floor so nothing is see-through.
var prefabPath = "Assets/Prefabs/Kazuko.prefab";
if (EditorApplication.isPlayingOrWillChangePlaymode)
    return "ERROR: Unity is in play mode, cannot modify prefab.";

var contents = PrefabUtility.LoadPrefabContents(prefabPath);
var report = new System.Text.StringBuilder();
try
{
    Transform Find(string n)
    {
        foreach (var t in contents.GetComponentsInChildren<Transform>(true))
            if (t.name == n) return t;
        return null;
    }

    var hipL = Find("Hip_L");
    var hipR = Find("Hip_R");
    var eyeL = Find("Eye1_L");
    var eyeR = Find("Eye1_R");
    var headM = Find("Head_M");
    var rootM = Find("Root_M");
    var root = contents.transform;
    if (hipL == null || hipR == null || rootM == null || eyeL == null || eyeR == null)
        return "ERROR: key bones not found";

    Vector3 pelvis = (hipL.position + hipR.position) * 0.5f;
    Vector3 fwd = ((eyeL.position + eyeR.position) * 0.5f - (headM != null ? headM.position : pelvis));
    fwd.y = 0f;
    fwd = fwd.sqrMagnitude > 1e-8f ? fwd.normalized : Vector3.forward;
    Vector3 rightDir = Vector3.Cross(Vector3.up, fwd).normalized;

    // ---------- measure skin + bikini cross-sections per height band ----------
    SkinnedMeshRenderer FindSmr(string meshName)
    {
        foreach (var r in contents.GetComponentsInChildren<SkinnedMeshRenderer>(true))
            if (r.sharedMesh != null && r.sharedMesh.name == meshName) return r;
        return null;
    }
    var skinSmr = FindSmr("Kazuko_skin");
    var bikiSmr = FindSmr("BikiniB");
    if (skinSmr == null) return "ERROR: Kazuko_skin SMR not found";

    const float bandStep = 0.05f;
    const int bandCount = 14; // y 0.50 .. 1.15
    var mLat = new float[bandCount];
    var mFront = new float[bandCount];
    var mBack = new float[bandCount];
    var mLegL = new float[bandCount];
    var mLegR = new float[bandCount];
    var mLegRc = new float[bandCount];
    var legCntL = new int[bandCount];
    var legCntR = new int[bandCount];

    void Measure(SkinnedMeshRenderer smr)
    {
        var l2w = smr.transform.localToWorldMatrix;
        foreach (var v in smr.sharedMesh.vertices)
        {
            Vector3 w = l2w.MultiplyPoint3x4(v);
            Vector3 rel = w - pelvis;
            float lat = Vector3.Dot(rel, rightDir);
            float front = Vector3.Dot(rel, fwd);
            if (Mathf.Abs(lat) > 0.2f) continue;
            int bi = Mathf.Clamp(Mathf.FloorToInt((w.y - 0.50f) / bandStep), 0, bandCount - 1);
            if (Mathf.Abs(lat) > mLat[bi]) mLat[bi] = Mathf.Abs(lat);
            if (front > mFront[bi]) mFront[bi] = front;
            if (-front > mBack[bi]) mBack[bi] = -front;
            if (lat < -0.05f) { mLegL[bi] += lat; legCntL[bi]++; }
            if (lat > 0.05f) { mLegR[bi] += lat; legCntR[bi]++; }
        }
    }
    Measure(skinSmr);
    if (bikiSmr != null) Measure(bikiSmr);

    var prof = new System.Text.StringBuilder();
    for (int i = 0; i < bandCount; i++)
    {
        float y = 0.50f + i * bandStep;
        float legL = legCntL[i] > 0 ? mLegL[i] / legCntL[i] : -Mathf.Lerp(0.081f, 0.060f, Mathf.Clamp01((0.96f - y) / 0.37f));
        float legR = legCntR[i] > 0 ? mLegR[i] / legCntR[i] : Mathf.Lerp(0.081f, 0.060f, Mathf.Clamp01((0.96f - y) / 0.37f));
        // thigh radius: farthest leg-side point from its leg center
        float rc = 0.052f;
        if (legCntR[i] > 0) rc = Mathf.Max(mLat[bi: 0], 0); // placeholder replaced below
        mLegL[i] = legL; mLegR[i] = legR;
        prof.Append(y.ToString("F2") + ":lat" + mLat[i].ToString("F3") + "/f" + mFront[i].ToString("F3") + "/b" + mBack[i].ToString("F3") + "/L" + legL.ToString("F3") + "/R" + legR.ToString("F3") + " ");
    }
    report.AppendLine("bands " + prof.ToString());
    return "DEBUG_STOP";

    // thigh radius per band: max distance from leg center among leg-side verts (second pass)
    var mThigh = new float[bandCount];
    void MeasureThigh(SkinnedMeshRenderer smr)
    {
        var l2w = smr.transform.localToWorldMatrix;
        foreach (var v in smr.sharedMesh.vertices)
        {
            Vector3 w = l2w.MultiplyPoint3x4(v);
            Vector3 rel = w - pelvis;
            float lat = Vector3.Dot(rel, rightDir);
            float front = Vector3.Dot(rel, fwd);
            if (Mathf.Abs(lat) > 0.2f) continue;
            int bi = Mathf.Clamp(Mathf.FloorToInt((w.y - 0.50f) / bandStep), 0, bandCount - 1);
            float c = lat < 0 ? mLegL[bi] : mLegR[bi];
            float r = Mathf.Sqrt((lat - c) * (lat - c) + front * front);
            if (lat < -0.03f || lat > 0.03f)
                if (r > mThigh[bi]) mThigh[bi] = r;
        }
    }
    MeasureThigh(skinSmr);
    if (bikiSmr != null) MeasureThigh(bikiSmr);

    float BandVal(float[] a, float y)
    {
        float f = Mathf.Clamp((y - 0.50f) / bandStep, 0f, bandCount - 1.001f);
        int i = Mathf.FloorToInt(f);
        return Mathf.Lerp(a[i], a[Mathf.Min(i + 1, bandCount - 1)], f - i);
    }
    float LegLatAt(float y, float sideSign)
    {
        return BandVal(sideSign < 0 ? mLegL : mLegR, y);
    }
    float ThighRAt(float y)
    {
        float r = BandVal(mThigh, y);
        return Mathf.Max(r, 0.045f);
    }
    report.AppendLine("thighR@0.65=" + ThighRAt(0.65f).ToString("F3") + " @0.75=" + ThighRAt(0.75f).ToString("F3") + " lat@0.95=" + BandVal(mLat, 0.95f).ToString("F3") + " front@0.95=" + BandVal(mFront, 0.95f).ToString("F3") + " back@0.90=" + BandVal(mBack, 0.90f).ToString("F3"));

    // ---------- texture: white cloth, subtle pleats, light-gray hem band ----------
    int TW = 256, TH = 256;
    var tex = new Texture2D(TW, TH, TextureFormat.RGBA32, false);
    for (int y = 0; y < TH; y++)
    {
        float v = (float)y / (TH - 1);
        for (int x = 0; x < TW; x++)
        {
            float u = (float)x / (TW - 1);
            float c = 0.95f; // white base
            if (v < 0.07f) c = 0.62f;                    // hem band (darker)
            else if (v < 0.12f) c = 0.80f;               // soft transition ring
            float pleat = ((int)(u * 14f) % 2 == 0) ? 1.0f : 0.975f; // vertical pleats
            c *= pleat;
            tex.SetPixel(x, y, new Color(c, c, c, 1f));
        }
    }
    tex.Apply();
    string texPath = "Assets/Textures/Kazuko/Kazuko_Bloomers.png";
    System.IO.File.WriteAllBytes(texPath, tex.EncodeToPNG());
    UnityEngine.Object.DestroyImmediate(tex);
    AssetDatabase.ImportAsset(texPath);
    var importer = (TextureImporter)AssetImporter.GetAtPath(texPath);
    if (importer != null)
    {
        importer.sRGBTexture = true;
        importer.mipmapEnabled = true;
        importer.wrapMode = TextureWrapMode.Repeat;
        importer.SaveAndReimport();
    }
    var texAsset = AssetDatabase.LoadAssetAtPath<Texture2D>(texPath);
    if (texAsset == null) return "ERROR: texture import failed";
    report.AppendLine("tex OK " + texPath);

    // ---------- material ----------
    var cloth = AssetDatabase.LoadAssetAtPath<Material>("Assets/Arts/Materials/kazuko/kazuko_cloth.mat");
    if (cloth == null) return "ERROR: kazuko_cloth.mat not found";
    string matPath = "Assets/Arts/Materials/kazuko/kazuko_bloomers.mat";
    if (AssetDatabase.LoadAssetAtPath<Material>(matPath) != null) AssetDatabase.DeleteAsset(matPath);
    var mat = new Material(cloth.shader);
    mat.CopyPropertiesFromMaterial(cloth);
    mat.SetTexture("_MainTex", texAsset);
    mat.SetColor("_MainColor", Color.white);
    mat.name = "kazuko_bloomers";
    AssetDatabase.CreateAsset(mat, matPath);
    report.AppendLine("mat OK " + matPath);

    // ---------- remove previous bloomers (idempotent) ----------
    var toDestroy = new System.Collections.Generic.List<GameObject>();
    foreach (var t in contents.GetComponentsInChildren<Transform>(true))
        if (t.name == "Bloomers") toDestroy.Add(t.gameObject);
    foreach (var g in toDestroy) UnityEngine.Object.DestroyImmediate(g);
    if (toDestroy.Count > 0) report.AppendLine("removed " + toDestroy.Count + " old bloomers");

    // ---------- build the peanut-shell bloomers ----------
    int N = 24;          // samples around the ring
    int levels = 12;      // height levels: top -> hem
    float topY = 1.06f, hemY = 0.62f;

    float[] LevelY = new float[levels];
    for (int j = 0; j < levels; j++) LevelY[j] = Mathf.Lerp(topY, hemY, (float)j / (levels - 1));

    var verts = new System.Collections.Generic.List<Vector3>();
    var uvs = new System.Collections.Generic.List<Vector2>();
    var nrm = new System.Collections.Generic.List<Vector3>();
    var shapeWin = new System.Collections.Generic.List<int>();

    // ray-exit helpers in the (lat, back) plane
    float RayCircle(float dx, float dz, float cx, float r)
    {
        float b = -2f * (dx * cx);           // equation t^2 - 2 t (d.c) + (c^2 - r^2) = 0
        float c = cx * cx - r * r;
        float disc = b * b - 4f * c;
        if (disc < 0f) return -1f;
        return (-b + Mathf.Sqrt(disc)) * 0.5f;
    }
    float RayEllipse(float dx, float dz, float cz, float rx, float rz)
    {
        float A = (dx * dx) / (rx * rx) + (dz * dz) / (rz * rz);
        float B = -2f * dz * cz / (rz * rz);
        float C = (cz * cz) / (rz * rz) - 1f;
        float disc = B * B - 4f * A * C;
        if (disc < 0f) return -1f;
        return (-B + Mathf.Sqrt(disc)) * 0.5f / 1f / A * A; // t = (-B + sqrt) / (2A)
    }

    for (int j = 0; j < levels; j++)
    {
        float y = LevelY[j];
        // hip ellipse (fades out below the crotch split)
        float f = Mathf.Clamp01((y - 0.66f) / 0.19f);
        float fade = f * f * (3f - 2f * f);
        float e_rx = Mathf.Max((BandVal(mLat, y) + 0.013f) * fade, 0.015f);
        float e_rf = Mathf.Max((BandVal(mFront, y) + 0.013f) * fade, 0.012f);
        float e_rb = Mathf.Max((BandVal(mBack, y) + 0.013f) * fade, 0.012f);
        float e_cz = (e_rb - e_rf) * 0.5f;
        float e_rz = (e_rb + e_rf) * 0.5f;
        // thigh lobes (lantern puff)
        float bell = Mathf.Exp(-Mathf.Pow((y - 0.70f) / 0.09f, 2f));
        float puff = 0.014f + 0.010f * bell;
        float legLatAbs = Mathf.Max(Mathf.Abs(LegLatAt(y, -1f)), Mathf.Abs(LegLatAt(y, +1f)));
        float legR = Mathf.Max(ThighRAt(y) + puff, legLatAbs + 0.006f);
        float cL = LegLatAt(y, -1f);
        float cR = LegLatAt(y, +1f);

        for (int i = 0; i < N; i++)
        {
            float th = 2f * Mathf.PI * i / N;
            float dx = Mathf.Cos(th), dz = Mathf.Sin(th);
            float tE = RayEllipse(dx, dz, e_cz, e_rx, e_rz);
            float tL = RayCircle(dx, dz, cL, legR);
            float tR = RayCircle(dx, dz, cR, legR);
            float t = Mathf.Max(tE, Mathf.Max(tL, tR));
            if (t <= 0.001f) t = 0.05f;
            float lat = dx * t, back = dz * t;
            int win = (tE >= tL && tE >= tR) ? 0 : (tL >= tR ? 1 : 2);
            float cxw = win == 0 ? 0f : (win == 1 ? cL : cR);
            Vector2 outward = new Vector2(lat - cxw, back - e_cz * (win == 0 ? 1f : 0f)).normalized;
            Vector3 p = pelvis + rightDir * lat + fwd * back;
            p.y = y;
            verts.Add(p);
            uvs.Add(new Vector2((float)i / N, Mathf.InverseLerp(hemY, topY, y)));
            nrm.Add((rightDir * outward.x + fwd * outward.y).normalized);
            shapeWin.Add(win);
        }
    }

    var tris = new System.Collections.Generic.List<int>();
    int Idx(int j, int i) { return j * N + (i % N); }
    for (int j = 0; j < levels - 1; j++)
        for (int i = 0; i < N; i++)
        {
            int a = Idx(j, i), b = Idx(j, i + 1), c = Idx(j + 1, i + 1), d = Idx(j + 1, i);
            tris.AddRange(new int[] { a, b, c, a, c, d });
        }

    // top cap (hidden under the skirt): fan level0 ring to a center point slightly below
    int topCenter = verts.Count;
    Vector3 tc = pelvis; tc.y = topY - 0.03f;
    verts.Add(tc); uvs.Add(new Vector2(0.5f, 1f)); nrm.Add(Vector3.up);
    for (int i = 0; i < N; i++)
        tris.AddRange(new int[] { Idx(0, i), Idx(0, i + 1), topCenter });

    // leg floors: per lobe, a dome from the hem ring up into the tube (fabric floor the thigh pierces)
    int hemBase = (levels - 1) * N;
    for (int s = 0; s < 2; s++)
    {
        float sideSign = s == 0 ? -1f : 1f;
        float c = s == 0 ? LegLatAt(hemY, -1f) : LegLatAt(hemY, +1f);
        // collect this lobe's arc (ring order), sharing the crossing samples (|lat| small)
        var arcIdx = new System.Collections.Generic.List<int>();
        for (int i = 0; i < N; i++)
        {
            Vector3 hv = verts[hemBase + i];
            float lat = Vector3.Dot(hv - pelvis, rightDir);
            if (lat * sideSign > -0.008f) arcIdx.Add(i);
        }
        if (arcIdx.Count < 3) continue;
        int midStart = verts.Count;
        for (int k = 0; k < arcIdx.Count; k++)
        {
            Vector3 hv = verts[hemBase + arcIdx[k]];
            float lat = Vector3.Dot(hv - pelvis, rightDir);
            float back = Vector3.Dot(hv - pelvis, fwd);
            float mLat2 = Mathf.Lerp(lat, c, 0.5f);
            Vector3 p = pelvis + rightDir * mLat2 + fwd * (back * 0.5f);
            p.y = hemY + 0.032f;
            verts.Add(p);
            uvs.Add(new Vector2((float)arcIdx[k] / N, 0.04f));
            nrm.Add(Vector3.down);
        }
        int apex = verts.Count;
        Vector3 ap = pelvis + rightDir * c; ap.y = hemY + 0.055f;
        verts.Add(ap); uvs.Add(new Vector2(0.5f, 0.02f)); nrm.Add(Vector3.down);
        for (int k = 0; k < arcIdx.Count - 1; k++)
        {
            int h0 = hemBase + arcIdx[k], h1 = hemBase + arcIdx[k + 1];
            int m0 = midStart + k, m1 = midStart + k + 1;
            tris.AddRange(new int[] { h0, h1, m1, h0, m1, m0 });
            tris.AddRange(new int[] { m0, m1, apex });
        }
    }

    // double-sided back copy
    int vCount = verts.Count;
    for (int vi = 0; vi < vCount; vi++) { verts.Add(verts[vi]); uvs.Add(uvs[vi]); nrm.Add(-nrm[vi]); }
    int triCount = tris.Count;
    for (int ti = 0; ti < triCount; ti += 3)
        tris.AddRange(new int[] { vCount + tris[ti + 2], vCount + tris[ti + 1], vCount + tris[ti] });

    // ---------- assemble skinned mesh ----------
    var go = new GameObject("Bloomers");
    go.transform.SetParent(root, false);
    Matrix4x4 go2world = go.transform.localToWorldMatrix;
    for (int vi = 0; vi < verts.Count; vi++) verts[vi] = go.transform.InverseTransformPoint(verts[vi]);

    var boneTs = new Transform[] { rootM, hipL, hipR };
    var mesh = new Mesh();
    mesh.name = "Kazuko_Bloomers";
    mesh.SetVertices(verts);
    mesh.SetUVs(0, uvs);
    mesh.SetNormals(nrm);
    mesh.SetTriangles(tris, 0);
    var binds = new Matrix4x4[3];
    for (int b = 0; b < 3; b++) binds[b] = boneTs[b].worldToLocalMatrix * go2world;
    mesh.bindposes = binds;

    var bw = new BoneWeight[verts.Count];
    for (int vi = 0; vi < verts.Count; vi++)
    {
        float y = Mathf.Lerp(hemY, topY, uvs[vi].y);
        float lat = 0f;
        // recompute world-ish lat from the local vert via go transform (approx: use original world vert)
        // (verts were converted in-place; use the stored uv-only approximation via original list copy is complex,
        //  so approximate lat by sampling the corresponding front-copy vert)
        int srcIdx = vi < vCount ? vi : vi - vCount;
        // recompute from world position before conversion is not available; use mesh-space x via rightDir:
        // simpler: derive from the original world vert stored earlier (we overwrote it), so recompute:
        //   we kept shapeWin only; use the bind pose world lat captured in a parallel list below.
        bw[vi] = new BoneWeight { boneIndex0 = 0, weight0 = 1f };
    }
    report.AppendLine("placeholder reached");
    return "STOP2";
}
finally
{
    PrefabUtility.UnloadPrefabContents(contents);
}

// White puffy lantern bloomers under the skirt, over the bikini (anti-peek, gacha-style).
// Measures skin+bikini cross-sections, lofts a peanut shell (hip ellipse + two thigh lobes),
// closes each leg with a domed fabric floor so no angle is see-through.
var prefabPath = "Assets/Prefabs/Kazuko.prefab";
if (EditorApplication.isPlayingOrWillChangePlaymode)
