            float front = Vector3.Dot(rel, fwd);
            if (Mathf.Abs(lat) > 0.2f) continue;
            int bi = Mathf.Clamp(Mathf.FloorToInt((w.y - 0.50f) / bandStep), 0, bandCount - 1);
            if (Mathf.Abs(lat) > mLat[bi]) mLat[bi] = Mathf.Abs(lat);
            if (front > mFront[bi]) mFront[bi] = front;
            if (-front > mBack[bi]) mBack[bi] = -front;
            if (lat < -0.05f) { mLegL[bi] += lat; legCntL[bi]++; }
            if (lat > 0.05f) { mLegR[bi] += lat; legCntR[bi]++; }
