var prefabPath = "Assets/Prefabs/Kazuko.prefab";
var contents = PrefabUtility.LoadPrefabContents(prefabPath);
try
{
    var sb = new System.Text.StringBuilder();
    foreach (var smr in contents.GetComponentsInChildren<SkinnedMeshRenderer>(true))
    {
        if (smr.name != "Bloomers") continue;
        var m = smr.sharedMesh;
        var b = m.bounds;
        var l2w = smr.transform.localToWorldMatrix;
        Vector3 wMin = l2w.MultiplyPoint3x4(b.center - b.extents);
        Vector3 wMax = l2w.MultiplyPoint3x4(b.center + b.extents);
        sb.AppendLine("Bloomers worldY range: " + wMin.y.ToString("F3") + " .. " + wMax.y.ToString("F3"));
        // sample the hem ring: last level verts (indices (levels-1)*N..) — find min y among all verts instead
        float minY = 99f, maxY = -99f;
        var vs = m.vertices;
        foreach (var v in vs) { var w = l2w.MultiplyPoint3x4(v); if (w.y < minY) minY = w.y; if (w.y > maxY) maxY = w.y; }
        sb.AppendLine("vertex worldY: " + minY.ToString("F3") + " .. " + maxY.ToString("F3"));
        sb.AppendLine("bones=" + smr.bones.Length + " mat=" + (smr.sharedMaterial ? smr.sharedMaterial.name : "null"));
    }
    return sb.ToString();
}
finally { PrefabUtility.UnloadPrefabContents(contents); }

