var prefabPath = "Assets/Prefabs/Kazuko.prefab";
var contents = PrefabUtility.LoadPrefabContents(prefabPath);
try
{
    var hipL = System.Linq.Enumerable.FirstOrDefault(contents.GetComponentsInChildren<Transform>(true), t => t.name == "Hip_L");
    var hipR = System.Linq.Enumerable.FirstOrDefault(contents.GetComponentsInChildren<Transform>(true), t => t.name == "Hip_R");
    var eyeL = System.Linq.Enumerable.FirstOrDefault(contents.GetComponentsInChildren<Transform>(true), t => t.name == "Eye1_L");
    var eyeR = System.Linq.Enumerable.FirstOrDefault(contents.GetComponentsInChildren<Transform>(true), t => t.name == "Eye1_R");
    var headM = System.Linq.Enumerable.FirstOrDefault(contents.GetComponentsInChildren<Transform>(true), t => t.name == "Head_M");
    Vector3 pelvis = (hipL.position + hipR.position) * 0.5f;
    Vector3 fwd = ((eyeL.position + eyeR.position) * 0.5f - (headM != null ? headM.position : pelvis));
    fwd.y = 0; fwd = fwd.normalized;
    Vector3 rightDir = Vector3.Cross(Vector3.up, fwd).normalized;

    SkinnedMeshRenderer FindSmr(string n)
    {
        foreach (var r in contents.GetComponentsInChildren<SkinnedMeshRenderer>(true))
            if (r.sharedMesh != null && r.sharedMesh.name == n) return r;
        return null;
    }
    var armor = FindSmr("Kasuko_armor");
    if (armor == null) return "armor not found";

    // skirt hem per 12 angular sectors (30 deg each), flared shell verts only
    int S = 12;
    var minY = new float[S];
    for (int i = 0; i < S; i++) minY[i] = 1.2f;
    var l2w = armor.transform.localToWorldMatrix;
    foreach (var v in armor.sharedMesh.vertices)
    {
        Vector3 w = l2w.MultiplyPoint3x4(v);
        if (w.y > 1.05f || w.y < 0.5f) continue;
        Vector3 rel = w - pelvis;
        float lat = Vector3.Dot(rel, rightDir);
        float back = -Vector3.Dot(rel, fwd);
        float r = Mathf.Sqrt(lat * lat + back * back);
        if (r < 0.10f || r > 0.45f) continue;
        float ang = Mathf.Atan2(lat, back); // 0 = back, +PI/2 = right, -PI/2 = left, PI = front
        int s = Mathf.Clamp((int)(((ang + Mathf.PI) / (2f * Mathf.PI)) * S), 0, S - 1);
        if (w.y < minY[s]) minY[s] = w.y;
    }
    var sb = new System.Text.StringBuilder();
    for (int i = 0; i < S; i++)
    {
        float ang = -Mathf.PI + (i + 0.5f) * 2f * Mathf.PI / S;
        string where = Mathf.Abs(ang) < 0.6f ? "back" : (Mathf.Abs(Mathf.PI - Mathf.Abs(ang)) < 0.6f ? "front" : "side");
        sb.AppendLine("sector " + i + " ang=" + (ang * 57.3f).ToString("F0") + "deg (" + where + (ang > 0 ? "+R" : "-L") + "): min y = " + (minY[i] >= 1.2f ? "none" : minY[i].ToString("F3")));
    }
    return sb.ToString();
}
finally { PrefabUtility.UnloadPrefabContents(contents); }

